class Solution {
public:
    long long maximumBeauty(vector<int>& flowers,
                            long long newFlowers,
                            int target,
                            int full,
                            int partial) {
        int n = flowers.size();

        for (int& x : flowers)
            x = min(x, target);

        sort(flowers.begin(), flowers.end());

        // Count gardens that are already complete.
        int incompleteCount = 0;

        while (incompleteCount < n &&
               flowers[incompleteCount] < target) {
            ++incompleteCount;
        }

        // All gardens already complete.
        if (incompleteCount == 0)
            return 1LL * n * full;

        // Prefix sums of incomplete gardens.
        vector<long long> prefix(incompleteCount + 1, 0);

        for (int i = 0; i < incompleteCount; ++i) {
            prefix[i + 1] = prefix[i] + flowers[i];
        }

        long long ans = 0;
        long long remaining = newFlowers;

        int alreadyFull = n - incompleteCount;

        // Complete the largest incomplete gardens first.
        for (int complete = 0;
             complete <= incompleteCount;
             ++complete) {

            if (complete > 0) {
                int idx = incompleteCount - complete;

                remaining -= target - flowers[idx];
            }

            if (remaining < 0)
                break;

            int left = incompleteCount - complete;

            long long beauty =
                1LL * (alreadyFull + complete) * full;

            if (left == 0) {
                ans = max(ans, beauty);
                continue;
            }

            int low = 0;
            int high = left - 1;
            int best = 0;

            while (low <= high) {
                int mid = low + (high - low) / 2;

                long long cost =
                    1LL * flowers[mid] * (mid + 1)
                    - prefix[mid + 1];

                if (cost <= remaining) {
                    best = mid;
                    low = mid + 1;
                } else {
                    high = mid - 1;
                }
            }

            long long cost =
                1LL * flowers[best] * (best + 1)
                - prefix[best + 1];

            long long minFlowers =
                flowers[best] +
                (remaining - cost) / (best + 1);

            minFlowers = min(minFlowers,
                             1LL * target - 1);

            beauty += minFlowers * partial;

            ans = max(ans, beauty);
        }

        return ans;
    }
};
